public class AcceptMatchAction : DockingAction {

	private static readonly string MENU_GROUP = VTPlugin.EDIT_MENU_GROUP;

	private VTController controller;

	public AcceptMatchAction(VTController controller) : base("Accept", VTPlugin.OWNER)
    {
		this.controller = controller;

		Icon icon = new GIcon("icon.version.tracking.action.accept.match");
		setToolBarData(new ToolBarData(icon, MENU_GROUP));
		setPopupMenuData(new MenuData(new string[] { "Accept" }, icon, MENU_GROUP));
		setEnabled(false);
		setHelpLocation(new HelpLocation("VersionTrackingPlugin", "Accept_Match"));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		List<VTMatch> selectedMatches;
		if (context is VTMatchContext) {
			VTMatchContext matchContext = (VTMatchContext) context;
			selectedMatches = matchContext.getSelectedMatches();
		}
		else if (context is VTMatchOneToManyContext) {
			VTMatchOneToManyContext matchContext = (VTMatchOneToManyContext) context;
			selectedMatches = matchContext.getSelectedMatches();
		}
		else {
			return;
		}
		AcceptMatchTask task = new AcceptMatchTask(controller, selectedMatches);
		controller.runVTTask(task);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		List<VTMatch> selectedMatches;
		if (context is VTMatchContext) {
			VTMatchContext matchContext = (VTMatchContext) context;
			selectedMatches = matchContext.getSelectedMatches();
		}
		else if (context is VTMatchOneToManyContext) {
			VTMatchOneToManyContext matchContext = (VTMatchOneToManyContext) context;
			selectedMatches = matchContext.getSelectedMatches();
		}
		else {
			selectedMatches = new List<VTMatch>();
		}
		return (selectedMatches.size() > 0);
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		return true;
	}
}
